const body = $input.first().json.body;
const messaging = body?.entry?.[0]?.messaging?.[0];

if (!messaging) return [];

const psid = String(messaging?.sender?.id || '');
const texto = messaging?.message?.text || '';
// Meta sends timestamp in milliseconds; Date.now() also in ms
const unixTs = messaging?.timestamp || Date.now();
const d = new Date(unixTs);
const offsetMs = -5 * 60 * 60 * 1000;
const panamaTime = new Date(d.getTime() + offsetMs);
const pad = n => String(n).padStart(2, '0');
const timestamp = pad(panamaTime.getUTCDate()) + '/' + pad(panamaTime.getUTCMonth()+1) + '/' + panamaTime.getUTCFullYear() + ' ' + pad(panamaTime.getUTCHours()) + ':' + pad(panamaTime.getUTCMinutes());

const referral = messaging?.referral || messaging?.message?.referral;
const has_referral = !!referral;

return [{
  json: {
    psid,
    texto,
    timestamp,
    unix_ts: unixTs,
    has_referral,
    campaign_name: referral?.ads_context_data?.ad_title || null,
    campaign_id: referral?.campaign_id || null,
    ad_id: referral?.ad_id || null,
    adset_id: referral?.adset_id || null
  }
}];
